import org.springframework.http.CacheControl;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;
import java.util.concurrent.TimeUnit;

@RestController
public class ProductAssetController {

    @GetMapping("/api/v1/products/{id}/specifications")
    public ResponseEntity<ProductSpec> getProductSpecifications(@PathVariable String id) {
        ProductSpec spec = productDatabaseService.findSpecById(id);

        // Configure HTTP caching headers instructing CDN edge nodes and browsers
        // to cache the response for 1 hour, allowing stale data while revalidating in the background.
        CacheControl cacheControl = CacheControl.maxAge(1, TimeUnit.HOURS)
                .public()
                .mustRevalidate()
                .staleWhileRevalidate(15, TimeUnit.MINUTES);

        return ResponseEntity.ok()
                .cacheControl(cacheControl)
                .body(spec);
    }
}
